"""Build portfolio HTML from catalog and Markdown; requires Pandoc."""
from pathlib import Path
import json,html,subprocess,re
r=Path(__file__).resolve().parents[1];catalog=json.loads((r/'catalogo/disciplinas.json').read_text())
css='''*{box-sizing:border-box}body{margin:0;background:#f5f7f3;color:#20382e;font:17px/1.7 system-ui,sans-serif}header{background:#fff;border-bottom:1px solid #dce3d8;padding:22px max(20px,calc((100% - 1200px)/2))}header a{color:#20382e;font-weight:750;text-decoration:none}main{max-width:1200px;margin:auto;padding:42px 24px 70px}h1{font-size:clamp(28px,4vw,42px);line-height:1.2;letter-spacing:-1px;margin:12px 0 24px}h2{font-size:25px;margin-top:38px}p{max-width:80ch}a{color:#245c40;text-underline-offset:3px}small,.meta{font-size:13px;color:#5c7062}.lede{font-size:20px;color:#5c7062;max-width:75ch}.controls{display:flex;gap:14px;margin:30px 0;flex-wrap:wrap}.controls input,.controls select{font:inherit;border:1px solid #b9c9b8;border-radius:5px;padding:10px;background:#fff;color:#20382e}.controls input{flex:1;min-width:200px}.disciplines{list-style:none;padding:0}.discipline{display:grid;grid-template-columns:46px 1fr 150px;gap:18px;border-top:1px solid #d9e1d5;padding:22px 0;align-items:start}.discipline .n{font-size:13px;color:#657b68}.discipline a{font-size:20px;font-weight:650;text-decoration:none}.discipline p{margin:7px 0;font-size:14px;color:#5c7062}.badge{font-size:12px;padding:4px 8px;background:#e7eddd;border-radius:4px;justify-self:end;white-space:nowrap}.quick{display:grid;grid-template-columns:1fr 1fr;gap:30px;background:#e8eedf;padding:25px;border-radius:7px;margin:28px 0}.quick a{display:block;font-weight:650;margin:8px 0}.count{font-size:13px;margin:12px 0;color:#5c7062}pre{overflow:auto;background:#e8eedf;padding:20px;font-size:13px}code{font-size:.85em;overflow-wrap:anywhere}li{margin:8px 0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px;border-bottom:1px solid #d9e1d5;text-align:left}.content{max-width:90ch;overflow-wrap:anywhere}.foot{margin-top:45px;border-top:1px solid #d9e1d5;padding-top:20px;font-size:13px;color:#5c7062}:focus-visible{outline:3px solid #507638;outline-offset:3px}[hidden]{display:none!important}@media(max-width:650px){main{padding:28px 18px}.quick{grid-template-columns:1fr;gap:12px}.discipline{grid-template-columns:28px 1fr;gap:10px}.badge{grid-column:2;justify-self:start}.controls{display:block}.controls input,.controls select{width:100%;margin:6px 0}.discipline a{font-size:18px}}@media print{header,.controls{display:none}body{background:white}main{padding:0}.discipline{break-inside:avoid}}
'''
def shell(title,body,back):return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+css+'</style></head><body><header><a href="'+back+'">MBA AI Leadership · 4ABL</a></header><main>'+body+'</main></body></html>'
# Render documentation that was generated by organization; keep project baselines byte-identical.
readmes=[r/'README.md',*list((r/'docs').glob('*.md')),*list((r/'disciplinas').rglob('README.md'))]
readmes=[p for p in readmes if '/speakup-lovable/' not in p.as_posix() and '/speakup-sdd/' not in p.as_posix()]
outputs={p.resolve():(p.with_name('index.html') if p.name=='README.md' else p.with_suffix('.html')) for p in readmes if p!=r/'README.md'}
for md in readmes:
 if md==r/'README.md':continue
 out=outputs[md.resolve()];body=subprocess.check_output(['pandoc',str(md),'-t','html5'],text=True)
 def link(m):
  href=m[1]
  if href.startswith(('http:','https:','#','mailto:')):return m[0]
  absolute=(md.parent/href).resolve()
  if absolute in outputs:
   import os
   return 'href="'+os.path.relpath(outputs[absolute],out.parent)+'"'
  return m[0]
 body=re.sub(r'href="([^"]+)"',link,body)
 import os
 back=os.path.relpath(r/'index.html',out.parent)
 out.write_text(shell(md.read_text().splitlines()[0].lstrip('# '),'<div class="content">'+body+'</div><p class="foot"><a href="'+md.name+'">Fonte Markdown</a> · Material localizado não comprova entrega acadêmica.</p>',back))
labels={'com-projetos':'Projetos disponíveis','com-material':'Material localizado','sem-material-local':'Aguardando material'}
items=[]
for d in catalog:
 p=d['pasta'];extra='Nome completo pendente de confirmação.' if d['nome_oficial_pendente'] else 'Aulas, projetos, entregas e referências.'
 items.append('<li class="discipline" data-status="'+d['status']+'" data-search="'+html.escape(d['nome_exibido'].lower(),quote=True)+'"><span class="n">'+d['id']+'</span><div><a href="'+p+'/index.html">'+html.escape(d['nome_exibido'])+'</a><p>'+extra+'</p></div><span class="badge">'+labels[d['status']]+'</span></li>')
speak='disciplinas/21-vibe-coding-executivo/projetos/speakup'
body='''<span class="meta">ANTONIO FIGUEIREDO · PORTFÓLIO ACADÊMICO · 2026</span><h1>Projetos e aprendizados,<br>organizados por disciplina.</h1><p class="lede">Memória do MBA AI Leadership, turma 4ABL. Requisitos, experimentos, código e evidências, com o estado de cada trabalho registrado.</p><div class="quick"><section><strong>Vibe Coding Executivo</strong><a href="'''+speak+'''/speakup-sdd/docs/leitura.html">Ler a documentação e comparação SpeakUp →</a><a href="'''+speak+'''/index.html">Original e evolução SDD</a></section><section><strong>AI Core Concepts</strong><a href="disciplinas/02-ai-core-concepts/projetos/correlacao-cx/index.html">Explorar o projeto de correlação CX →</a><a href="disciplinas/02-ai-core-concepts/aulas/index.html">Resumos e aulas</a></section></div><h2>Disciplinas</h2><p class="meta">A ordem segue a imagem do portal. Títulos truncados continuam sinalizados; não representam nomes oficiais completos.</p><div class="controls"><input type="search" id="q" aria-label="Buscar disciplina" placeholder="Buscar disciplina"><select id="status" aria-label="Filtrar por conteúdo"><option value="">Todas as disciplinas</option value="com-projetos">Com projetos</option><option value="com-material">Com material</option><option value="sem-material-local">Aguardando material</option></select></div><p class="count" id="count" aria-live="polite"></p><ul class="disciplines">'''+''.join(items)+'''</ul><footer class="foot">Atualização: 19/10/2026 · <a href="docs/estrutura.html">Estrutura</a> · <a href="docs/organizacao-local.html">Origem e integridade</a> · <a href="docs/direitos-e-privacidade.html">Direitos e privacidade</a> · <a href="README.md">README</a><p>Acervo original restrito permanece local, fora do Git. Repositório privado; este portal não foi publicado na web.</p></footer><script>const q=document.querySelector('#q'),s=document.querySelector('#status'),items=[...document.querySelectorAll('.discipline')];function norm(v){return v.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();}function update(){let count=0;for(const item of items){const visible=norm(item.dataset.search).includes(norm(q.value))&&(!s.value||item.dataset.status===s.value);item.hidden=!visible;if(visible)count++;}document.querySelector('#count').textContent=count+' disciplinas exibidas';}q.addEventListener('input',update);s.addEventListener('change',update);update();</script>'''
if not (r/speak/'speakup-sdd/docs/leitura.html').is_file():
 body=body.replace(speak+'/speakup-sdd/docs/leitura.html',speak+'/index.html').replace('Ler a documentação e comparação SpeakUp →','Ver versões e pendências do SpeakUp →')
 body=body.replace('<h2>Disciplinas</h2>','<p class="meta"><strong>Importação parcial:</strong> arquivos do OneDrive ainda indisponíveis. Código SDD aguarda download; <a href="docs/importacao-pendente.html">consulte as pendências</a>.</p><h2>Disciplinas</h2>')
(r/'index.html').write_text(shell('MBA AI Leadership — 4ABL',body,'index.html'))

print('Portal atualizado:', r/'index.html')
